public class DbgengDebuggerPlatformOpinion : AbstractDebuggerPlatformOpinion {
	protected static readonly LanguageID LANG_ID_X86_64 = new LanguageID("x86:LE:64:default");
	protected static readonly LanguageID LANG_ID_X86_64_32 = new LanguageID("x86:LE:64:compat32");
	protected static readonly CompilerSpecID COMP_ID_VS = new CompilerSpecID("windows");
	protected static readonly Set<DisassemblyInject> INJECTS =
		Set.of(new DbgengX64DisassemblyInject());

	class Mode
{	public static readonly Mode X64 = new();
	public static readonly Mode X86 = new();
	public static readonly Mode UNK = new();


		static Mode computeFor(PluginTool tool, Trace trace, Address address, long snap) {
			DebuggerListingService listing = tool.getService(typeof(DebuggerListingService));
			AutoReadMemorySpec readSpec = listing.getAutoReadMemorySpec();

			DebuggerTargetService targetService = tool.getService(typeof(DebuggerTargetService));
			Target target = targetService == null ? null : targetService.getTarget(trace);
			DebuggerCoordinates coords = DebuggerCoordinates.NOWHERE
					// force host platform, or else we'll recurse and blow the stack
					.platform(trace.getPlatformManager().getHostPlatform())
					.snap(snap)
					.target(target);

			Collection<TraceModule> modules =
				trace.getModuleManager().getModulesAt(snap, address);
			Msg.debug(typeof(Mode), "Computing mode from modules: " +
				modules.stream().map(m => m.getName(snap)).collect(Collectors.joining(",")));
			Set<Mode> modes = modules.stream()
					.map(m => modeForModule(tool, readSpec, coords, m))
					.filter(m => m != UNK)
					.collect(Collectors.toSet());
			Msg.debug(typeof(Mode), "  Got mode(s): " + modes);
			if (modes.size() != 1) {
				return UNK;
			}
			return modes.iterator().next();
		}

		static Mode modeForModule(PluginTool tool, AutoReadMemorySpec readSpec,
				DebuggerCoordinates coords, TraceModule module) {
			AddressSet set = new AddressSet();
			Trace trace = coords.getTrace();
			long snap = coords.getSnap();
			Address @base = module.getBase(snap);
			set.add(@base, @base); // Recorder should read page
			try {
				readSpec.readMemory(tool, coords, set).get(1, TimeUnit.SECONDS);
				trace.flushEvents();
			}
			catch (Exception e) when (e is InterruptedException or ExecutionException or TimeoutException) {
				DebuggerConsoleService console = tool.getService(typeof(DebuggerConsoleService));
				string message = "Could not read PE header of %s to determine x86 vs x64 mode"
						.formatted(module.getName(snap));
				if (console != null) {
					console.log(DebuggerResources.ICON_LOG_ERROR, message, e);
				}
				else {
					Msg.error(typeof(Mode), message, e);
				}
				// Let it fall through in case stale memory is still accurate
			}
			MemBuffer bufferAt = trace.getMemoryManager().getBufferAt(snap, module.getBase(snap));
			try
{
    using (ByteProvider bp = new MemBufferByteProvider(bufferAt))
    {

				PortableExecutable pe =
					new PortableExecutable(bp, SectionLayout.MEMORY, false, false);
				NTHeader ntHeader = pe.getNTHeader();
				if (ntHeader == null) {
					return UNK;
				}
				OptionalHeader optionalHeader = ntHeader.getOptionalHeader();
				if (optionalHeader == null) {
					return UNK; // Really shouldn't happen, but who knows?
				}
				return optionalHeader.is64bit() ? X64 : X86;
			
    }
}
			catch (IOException e) {
				Msg.warn(typeof(Mode), "Could not parse PE from trace: " + e);
				return UNK;
			}
		}
	}

